/* The entry IS the projection: `entries` is dense, so a borrowed entry is a
   plain `&entries[idx]` and the cursor is an index test rather than a scan for
   the next live one. Insertion order, and nothing can perforate it. */
typedef z_t1498_entry_t z_t1508_t;

typedef struct {
    z_t1498_t* m;
    uint32_t idx;
} z_t1506_t;

static z_t1511_t z_t1506_call(z_t1506_t* _it);
static z_t1511_t z_t1506_call(z_t1506_t* _it) {
    z_t1511_t _out = {0};
    if (_it->idx < _it->m->length) {
        _out.tag = Z_OPTIONVIEW_IDMAPENTRYV_U64_U64_TAG_SOME;
        _out.data = &_it->m->entries[_it->idx];
        _it->idx++;
        return _out;
    }
    _out.tag = Z_OPTIONVIEW_IDMAPENTRYV_U64_U64_TAG_NONE;
    return _out;
}

static z_t1506_t z_t1498_iterateItems(const z_t1498_t* _this);
static z_t1506_t z_t1498_iterateItems(const z_t1498_t* _this) {
    z_t1506_t _it = {0};
    /* the same const stop as `get` and z_Set's `iterate`: OptionView's payload
       is a bare void*, so const cannot propagate into it */
    _it.m = (z_t1498_t*)_this;
    _it.idx = 0;
    return _it;
}

